'use strict';
const $=id=>document.getElementById(id), ACTIVE=new Set(['queued','downloading','extracting_audio','transcribing','analyzing','selecting_clips','rendering']);
const processingMode=()=>($('processingMode')?.value||'BALANCED');
let mode='upload',selectedFile=null,uploading=false,selectedJob=null;
const error=message=>{$('error').textContent=message||'';$('error').hidden=!message};
const chooseMode=v=>{mode=v;$('uploadSection').hidden=v!=='upload';$('urlSection').hidden=v!=='url';$('uploadTab').classList.toggle('selected',v==='upload');$('urlTab').classList.toggle('selected',v==='url');error('')};
$('uploadTab').onclick=()=>chooseMode('upload');$('urlTab').onclick=()=>chooseMode('url');$('uploadSection').onclick=()=>$('fileInput').click();$('uploadSection').ondragover=e=>e.preventDefault();$('uploadSection').ondrop=e=>{e.preventDefault();setFile(e.dataTransfer.files[0])};$('fileInput').onchange=e=>setFile(e.target.files[0]);
function setFile(f){if(f){selectedFile=f;$('fileName').textContent=f.name;$('fileDescription').textContent=(f.size/1048576).toFixed(1)+' MB ready to upload'}}
async function json(url,opt){const r=await fetch(url,opt);let d={};try{d=await r.json()}catch{}if(!r.ok)throw Error(typeof d.detail==='string'?d.detail:'Request failed');return d}
$('analyze').onclick=async()=>{if(uploading)return;uploading=true;$('analyze').disabled=true;error('');try{let d;if(mode==='upload'){if(!selectedFile)throw Error('Choose a video first.');d=await new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/upload');x.upload.onprogress=e=>{if(e.lengthComputable){$('progress').hidden=false;$('progressBar').style.width=Math.round(e.loaded/e.total*100)+'%'}};x.onload=()=>{let b={};try{b=JSON.parse(x.responseText)}catch{};x.status>=200&&x.status<300?resolve(b):reject(Error(b.detail||'Upload failed'))};x.onerror=()=>reject(Error('Upload failed'));const f=new FormData();f.append('file',selectedFile);x.send(f)})}else{const u=$('videoUrl').value.trim();if(!u)throw Error('Paste a public video URL first.');d=await json('/api/url',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url:u})})}selectedJob=d.job_id;await refresh()}catch(e){error(e.message)}finally{uploading=false;$('analyze').disabled=false;$('analyze').textContent='Generate my clips →';$('progress').hidden=true}};
function element(n,c,t){const e=document.createElement(n);if(c)e.className=c;if(t!==undefined)e.textContent=t;return e}function time(n){n=Math.round(n||0);return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`}
async function cancelJob(id){try{await json(`/api/jobs/${id}/cancel`,{method:'POST'});refresh()}catch(e){error(e.message)}}
async function retryJob(id){try{await json(`/api/jobs/${id}/retry`,{method:'POST'});selectedJob=id;refresh()}catch(e){error(e.message)}}
async function deleteJob(id){if(!confirm('Delete this project and all its files?'))return;try{await json(`/api/jobs/${id}`,{method:'DELETE'});if(selectedJob===id){selectedJob=null;$('clipSection').hidden=true;$('transcriptSection').hidden=true}refresh()}catch(e){error(e.message)}}
async function refresh(){try{const jobs=await json('/api/jobs');$('count').textContent=`${jobs.length} PROJECTS`;const area=$('jobs');area.replaceChildren();if(!jobs.length)area.append(element('div','empty','Your video projects will appear here.'));for(const j of jobs){const box=element('div','job');const detail=element('div','job-body');detail.append(element('strong','',j.source_url||j.filename||'Video project'));const row=element('div','job-meta');row.append(element('span',j.status,j.stage));if(j.metadata)row.append(element('span','',`${time(j.metadata.duration)} · ${j.metadata.width}×${j.metadata.height}`));if(j.progress!=null&&!String(j.stage||'').includes('%'))row.append(element('span','',`${Math.round(j.progress)}%`));detail.append(row);if(ACTIVE.has(j.status)){const track=element('div','job-progress-track'),fill=element('div','job-progress-fill');if(j.progress==null)fill.className+=' indeterminate';else fill.style.width=Math.max(2,Math.min(100,j.progress))+'%';track.append(fill);detail.append(track)}if(j.error)detail.append(element('p','job-error',j.error));const actions=element('div','job-links');if(j.status==='completed'){const b=element('button','outline','View clips');b.onclick=()=>showClips(j.id);actions.append(b)}if(j.transcript_path){const b=element('button','outline','Transcript');b.onclick=()=>showTranscript(j.id);actions.append(b)}if(ACTIVE.has(j.status)){const b=element('button','outline','Cancel');b.onclick=()=>cancelJob(j.id);actions.append(b)}if(['failed','cancelled','interrupted'].includes(j.status)){const b=element('button','outline','Retry');b.onclick=()=>retryJob(j.id);actions.append(b)}const del=element('button','outline','Delete');del.onclick=()=>deleteJob(j.id);actions.append(del);detail.append(actions);box.append(element('div','job-icon','▣'),detail);area.append(box)}if(selectedJob){const j=jobs.find(x=>x.id===selectedJob);if(j?.status==='completed'&&$('clipSection').dataset.job!==selectedJob)showClips(selectedJob)}}catch(e){console.error(e)}}
async function showTranscript(id){try{const d=await json(`/api/jobs/${id}/transcript`);$('transcriptSection').hidden=false;$('language').textContent=(d.language||'').toUpperCase();$('transcriptText').replaceChildren(...(d.segments||[]).map(s=>{const p=element('p');p.append(element('time','',time(s.start)+'  '));p.append(document.createTextNode(s.text));return p}))}catch(e){error(e.message)}}
async function showClips(id){try{selectedJob=id;const d=await json(`/api/jobs/${id}/clips`);$('clipSection').hidden=false;$('clipSection').dataset.job=id;$('downloadAll').href=`/api/jobs/${id}/download-all`;$('clipResults').replaceChildren();for(const c of d.clips){const box=element('article','clip-card'),v=element('video','clip-video');v.controls=true;v.src=`/api/jobs/${id}/clips/${c.id}/video`;v.setAttribute('playsinline','');box.append(v,element('h3','',c.title),element('div','score',`${c.score}/100 · ${time(c.start)}–${time(c.end)}`),element('p','clip-reason',c.reason));const a=element('a','outline','Download MP4');a.href=`/api/jobs/${id}/clips/${c.id}/download`;box.append(a);const b=element('button','outline','Edit & re-render');b.onclick=async()=>{const start=Number(prompt('Start seconds',c.start)),end=Number(prompt('End seconds',c.end)),theme=prompt('Theme: professional, yellow, minimal, karaoke',c.theme);if(!Number.isFinite(start)||!Number.isFinite(end)||!theme)return;try{await json(`/api/jobs/${id}/clips/${c.id}/rerender`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start,end,theme})});$('clipSection').dataset.job='';refresh()}catch(e){error(e.message)}};box.append(b);$('clipResults').append(box)}$('clipSection').scrollIntoView({behavior:'smooth'})}catch(e){error(e.message)}}
async function geminiStatus(){try{const d=await json('/api/settings/gemini');$('geminiStatus').textContent=(d.configured?'✓ KEY CONFIGURED':'KEY REQUIRED')+' · '+(d.model||'Gemini model unavailable')}catch{$('geminiStatus').textContent='CONNECTION ERROR'}}
$('saveGeminiKey').onclick=async()=>{try{await json('/api/settings/gemini',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({api_key:$('geminiKey').value.trim()})});$('geminiKey').value='';$('geminiMessage').textContent='Key saved on this computer.';geminiStatus()}catch(e){$('geminiMessage').textContent=e.message}};
$('removeGeminiKey').onclick=async()=>{$('geminiMessage').textContent=(await fetch('/api/settings/gemini',{method:'DELETE'})).ok?'Saved key removed.':'Could not remove key.';geminiStatus()};geminiStatus();refresh();setInterval(refresh,1800);
